/**
 * @param {Promise} promise1
 * @param {Promise} promise2
 * @return {Promise}
 */
var addTwoPromises = async function(promise1, promise2) {
    // Both promises are already running; Promise.all waits for both
    // and rejects immediately if either one rejects
    const [a, b] = await Promise.all([promise1, promise2]);
    // async functions always wrap the return value in a promise
    return a + b;
};

/**
 * addTwoPromises(Promise.resolve(2), Promise.resolve(2))
 *   .then(console.log); // 4
 */
